// Function to strip spaces, colons, dashes, etc. (leaves only letters and numbers)
const normalize = (text) => {
  return (text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '') // Removes spaces, punctuation, and special characters
    .trim();
};

// 1. Grab and normalize the target title using node context execution data
let requestedTitle = '';
try {
  requestedTitle = $('Jellyfin Media Request Form Sheet Connection').item.json['Title of Media'] || '';
} catch (e) {
  requestedTitle = $('Jellyfin Media Request Form Sheet Connection').first().json['Title of Media'] || '';
}
const targetTitleClean = normalize(requestedTitle);

// 2. Filter through the incoming Sonarr items
const incomingItems = $input.all();
let matchedItems = incomingItems.filter(item => {
  const sonarrTitle = item.json.title || '';
  const sonarrTitleClean = normalize(sonarrTitle);

  // Check the original native language
  const language = item.json.originalLanguage?.name || '';
  const isNativeEnglish = language.toLowerCase().trim() === 'english';

  // CRITICAL DUB MATCH: If the user typed the EXACT title name (normalized), 
  // we assume they explicitly want it regardless of native origin language.
  const isExactTitleMatch = sonarrTitleClean === targetTitleClean;

  // Fuzzy match string check
  const isFuzzyMatch = sonarrTitleClean.includes(targetTitleClean) || targetTitleClean.includes(sonarrTitleClean);

  // Keep the item if:
  // (It's a fuzzy title match AND natively English) OR (It's the exact specific title requested)
  return (isFuzzyMatch && isNativeEnglish) || isExactTitleMatch;
});

// 3. Fallback/Debug: If nothing matches, return the debug table
if (matchedItems.length === 0) {
  return [{
    json: {
      error: "No match found, or show failed English/Explicit Request filters",
      debug_sheet_title_received_normalized: targetTitleClean,
      debug_first_sonarr_title_checked_normalized: normalize(incomingItems[0]?.json?.title),
      debug_first_sonarr_language_checked: incomingItems[0]?.json?.originalLanguage?.name || "Unknown"
    }
  }];
}

return matchedItems;

