const normalize = (text) => {
  return (text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .trim();
};

// 1. Grab all incoming items from the Radarr HTTP Request
const incomingItems = $input.all();

// 2. Safely grab the Title from the current execution context
let requestedTitle = '';
try {
  // This looks at the exact input linked to this specific execution run
  requestedTitle = $('Jellyfin Media Request Form Sheet Connection').item.json['Title of Media'] || '';
} catch (e) {
  // Fallback to .first() if execution indexing is acting up
  requestedTitle = $('Jellyfin Media Request Form Sheet Connection').first().json['Title of Media'] || '';
}

const targetTitleClean = normalize(requestedTitle);

// 3. Filter through the Radarr items
let matchedItems = incomingItems.filter(item => {
  const radarrTitle = item.json.title || '';
  const radarrTitleClean = normalize(radarrTitle);

  // Safely extract the language name string from Radarr's payload object
  const language = item.json.originalLanguage?.name || '';
  const isEnglish = language.toLowerCase().trim() === 'english';

  // Requires both the normalized title match AND that the original language is English
  return (radarrTitleClean.includes(targetTitleClean) || targetTitleClean.includes(radarrTitleClean)) && isEnglish;
});

// 4. Fallback/Debug: If nothing matches, return the debug table
if (matchedItems.length === 0) {
  return [{
    json: {
      error: "No match found during Radarr filtering logic or movie is not in English",
      debug_sheet_title_received_normalized: targetTitleClean,
      debug_first_radarr_title_checked_normalized: normalize(incomingItems[0]?.json?.title),
      debug_first_radarr_language_checked: incomingItems[0]?.json?.originalLanguage?.name || "Unknown"
    }
  }];
}

return matchedItems;
